package net.civeira.phylax.feature.access.userscopeconsent.infrastructure.repository;

import java.util.Iterator;
import java.util.List;
import java.util.function.BiFunction;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.feature.access.userscopeconsent.domain.UserScopeConsent;
import net.civeira.phylax.feature.access.userscopeconsent.domain.gateway.UserScopeConsentCursor;
import net.civeira.phylax.feature.access.userscopeconsent.domain.gateway.UserScopeConsentFilter;

class UserScopeConsentSlider extends Slider<UserScopeConsent> {

  /**
   * @autogenerated SlideGenerator
   */
  private final UserScopeConsentCursor cursor;

  /**
   * @autogenerated SlideGenerator
   */
  private final UserScopeConsentFilter filter;

  /**
   * @autogenerated SlideGenerator
   */
  private final BiFunction<UserScopeConsentFilter, UserScopeConsentCursor, Iterator<UserScopeConsent>> gateway;

  /**
   * @autogenerated SlideGenerator
   * @param multi
   * @param limit
   * @param gateway
   * @param filter
   * @param cursor
   */
  UserScopeConsentSlider(final Iterator<UserScopeConsent> multi, final int limit,
      final BiFunction<UserScopeConsentFilter, UserScopeConsentCursor, Iterator<UserScopeConsent>> gateway,
      final UserScopeConsentFilter filter, final UserScopeConsentCursor cursor) {
    super(multi, limit);
    this.gateway = gateway;
    this.filter = filter;
    this.cursor = cursor;
  }

  /**
   * @autogenerated SlideGenerator
   * @param userScopeConsents
   * @param limit
   * @return
   */
  @Override
  public Iterator<UserScopeConsent> next(List<UserScopeConsent> userScopeConsents, int limit) {
    UserScopeConsent last = userScopeConsents.get(userScopeConsents.size() - 1);
    UserScopeConsentCursor cr = this.cursor.withSinceUid(last.getUid()).withLimit(limit);
    return gateway.apply(this.filter, cr);
  }
}
